fn main() {
    let plus_one = |value: i32| -> i32 { value + 1 };
    println!("{}", plus_one(8));
    // plus_one(String::from("8")) 会造成类型不匹配。
}

struct Memo<F: Fn(i32) -> i32> { compute: F, value: Option<i32> }
impl<F: Fn(i32) -> i32> Memo<F> {
    fn for_five(&mut self) -> i32 {
        if let Some(value) = self.value { return value; }
        let value = (self.compute)(5);
        self.value = Some(value);
        value
    }
}
fn main() {
    let mut memo = Memo { compute: |x| x * 4, value: None };
    println!("{} {}", memo.for_five(), memo.for_five());
}

struct Last<F: Fn(i32) -> i32> { compute: F, saved: Option<(i32, i32)> }
impl<F: Fn(i32) -> i32> Last<F> {
    fn value(&mut self, key: i32) -> i32 {
        if let Some((old, value)) = self.saved {
            if old == key { return value; }
        }
        let value = (self.compute)(key);
        self.saved = Some((key, value));
        value
    }
}
fn main() {
    let mut cache = Last { compute: |x| x * 2, saved: None };
    println!("{} {}", cache.value(3), cache.value(8));
}

