fn main() {
    let values = [1, 3, 5];
    let mapped = values.iter().map(|value| value * 10);
    let result: Vec<i32> = mapped.collect();
    println!("{:?}", result);
}

fn main() {
    let minimum = 6;
    let values = [2, 8, 6, 3];
    let selected: Vec<i32> = values.iter().copied()
        .filter(|value| *value >= minimum).collect();
    println!("{:?}", selected);
}

struct Steps { next_value: i32 }
impl Iterator for Steps {
    type Item = i32;
    fn next(&mut self) -> Option<i32> {
        if self.next_value > 3 { return None; }
        let value = self.next_value;
        self.next_value += 1;
        Some(value)
    }
}
fn main() {
    let values: Vec<i32> = Steps { next_value: 1 }.collect();
    println!("{:?}", values);
}

struct Config { query: String, path: String }
fn config(mut args: impl Iterator<Item = String>) -> Result<Config, &'static str> {
    args.next();
    let query = args.next().ok_or("missing query")?;
    let path = args.next().ok_or("missing path")?;
    if args.next().is_some() { return Err("too many arguments"); }
    Ok(Config { query, path })
}
fn main() {
    let args = vec!["finder", "bird", "notes.txt"].into_iter().map(String::from);
    let c = config(args).expect("complete example arguments");
    println!("{} {}", c.query, c.path);
}

fn search<'a>(query: &str, text: &'a str) -> Vec<&'a str> {
    text.lines().filter(|line| line.contains(query)).collect()
}
fn main() {
    let lines = search("sun", "sun above
rain below
sun again");
    println!("{:?}", lines);
}

fn with_loop(values: &[i32]) -> i32 {
    let mut total = 0;
    for value in values { total += value; }
    total
}
fn with_iterator(values: &[i32]) -> i32 { values.iter().copied().sum() }
fn main() {
    let values = [2, 4, 8];
    assert_eq!(with_loop(&values), with_iterator(&values));
    println!("{}", with_iterator(&values));
}

fn main() {
    let offset = 2;
    let values = [1, 4, 7];
    let total: i32 = values.iter().map(|value| value + offset).sum();
    println!("{}", total);
}
